WHERE r.id = v.id::uuid AND r.is_deleted = FALSE;

-- Check: filled fields per register.
SELECT l.register_key, count(*) AS sample_records, round(avg((SELECT count(*) FROM jsonb_object_keys(r.field_values)))) AS avg_fields_filled
FROM public.local_register_records r JOIN public.local_registers l ON l.id = r.register_id
WHERE r.id::text ~ '^00000000-0000-4000-a01[1-6]-'
GROUP BY l.register_key ORDER BY l.register_key;
